def try_config(r_a, r_b, val_a=3, val_b=2, bg=8):
    """Try configuration"""
    H, W = 12, 26
    grid = [[bg] * W for _ in range(H)]

    # Apply band A: rows r_a and r_a+1
    for rr in [r_a]:
        if rr < H:
            offset = rr - r_a  # always 0
            for c in range(W):
                if (c + offset) % 2 == 1:
                    grid[rr][c] = val_a

    # Apply band A second row
    for rr in [r_a + 1]:
        if rr < H:
            offset = rr - r_a
            for c in range(W):
                if (c + offset) % 2 == 1:
                    grid[rr][c] = val_a

    # Apply band B: similar
    for rr in [r_b]:
        if rr < H:
            offset = rr - r_b
            for c in range(W):
                if (c + offset) % 2 == 1:
                    grid[rr][c] = val_b

    for rr in [r_b + 1]:
        if rr < H:
            offset = rr - r_b
            for c in range(W):
                if (c + offset) % 2 == 1:
                    grid[rr][c] = val_b

    return grid

